# ---- helper predicates (from Logic.h / region-local macros) ------------
def BREAK_BOULDER_BEFORE_OR_BEAT_ALIENS_DAY(s):
    return (s.time_between(TIME_DAY1_AM_06_00, TIME_NIGHT1_PM_06_00) and CAN_BE_GORON(s) and s.has_item('ITEM_POWDER_KEG')) or s.event('RE_COWS_FROM_ALIENS')

def BREAK_BOULDER_BEFORE_OR_BEAT_ALIENS_NIGHT(s):
    return (s.time_between(TIME_NIGHT1_PM_06_00, TIME_NIGHT1_AM_02_30) and CAN_BE_GORON(s) and s.has_item('ITEM_POWDER_KEG')) or s.event('RE_COWS_FROM_ALIENS')

def CAN_BE_DEITY(s):
    return s.is_form('DEITY') or s.has_item('ITEM_MASK_FIERCE_DEITY')

def CAN_BE_DEKU(s):
    return s.is_form('DEKU') or s.has_item('ITEM_MASK_DEKU')

def CAN_BE_GORON(s):
    return s.is_form('GORON') or s.has_item('ITEM_MASK_GORON')

def CAN_BE_ZORA(s):
    return s.is_form('ZORA') or s.has_item('ITEM_MASK_ZORA')

def CAN_GROW_BEAN_PLANT(s):
    return s.has_item('ITEM_MAGIC_BEANS') and (s.can_play_song('STORMS') or (s.has_bottle() and (s.can_access('SPRING_WATER') or s.can_access('HOT_SPRING_WATER'))))

def CAN_HOOK_SCARECROW(s):
    return s.has_item('ITEM_OCARINA_OF_TIME') and s.has_item('ITEM_HOOKSHOT') and s.can_play_notes('OCARINA_SONG_SCARECROW_SPAWN')

def CAN_LIGHT_TORCH_NEAR_ANOTHER(s):
    return s.has_item('ITEM_DEKU_STICK') or s.can_use_magic_arrow('FIRE')

def CAN_RIDE_EPONA(s):
    return s.can_play_song('EPONA')

def CAN_TRAVERSE_WAIST_DEEP_WATER(s):
    return s.ability('SWIM') or CAN_BE_DEKU(s) or CAN_BE_ZORA(s) or CAN_BE_GORON(s)

def CAN_USE_DAY2_RAIN_BEAN(s):
    return CAN_GROW_BEAN_PLANT(s) or (s.has_item('ITEM_MAGIC_BEANS') and CLOCK_DAY2(s))

def CAN_USE_EXPLOSIVE(s):
    return s.has_item('ITEM_BOMB') or s.has_item('ITEM_BOMBCHU') or (s.has_item('ITEM_MASK_BLAST') and (s.equip_value('EQUIP_TYPE_SHIELD') > EQUIP_VALUE_SHIELD_NONE))

def CAN_USE_HUMAN_SWORD(s):
    return s.equip_value('EQUIP_TYPE_SWORD') >= EQUIP_VALUE_SWORD_KOKIRI

def CAN_USE_PROJECTILE(s):
    return s.has_item('ITEM_BOW') or s.has_item('ITEM_HOOKSHOT') or (CAN_BE_DEKU(s) and s.has_magic()) or CAN_BE_ZORA(s)

def CAN_USE_SWORD(s):
    return CAN_USE_HUMAN_SWORD(s) or s.has_item('ITEM_SWORD_GREAT_FAIRY') or CAN_BE_DEITY(s)

def CLOCK_DAY1(s):
    return s.owns_half_day(0)

def CLOCK_DAY2(s):
    return s.owns_half_day(2)

def CLOCK_DAY3(s):
    return s.owns_half_day(4)

def CLOCK_NIGHT1(s):
    return s.owns_half_day(1)

def CLOCK_NIGHT2(s):
    return s.owns_half_day(3)

def CLOCK_NIGHT3(s):
    return s.owns_half_day(5)

def CanGetPastBigOcto(s):
    return s.event('RE_SOUTHERN_SWAMP_RIDE_BOAT') or CanGetPastBigOctoWithoutBoat(s)

def CanGetPastBigOctoWithoutBoat(s):
    return (s.event('RE_SOUTHERN_SWAMP_KILL_OCTOROK') and CAN_BE_DEKU(s)) or (s.event('RE_CLEARED_WOODFALL_TEMPLE') and CAN_TRAVERSE_WAIST_DEEP_WATER(s))

def ClockFilter(s):
    return (not SettingClocks(s)) or (IS_DAY1(s) or IS_NIGHT1(s) or IS_DAY2(s) or IS_NIGHT2(s) or IS_DAY3(s) or IS_NIGHT3(s))

def FINAL_DAY(s):
    return IS_DAY3(s) or IS_NIGHT3(s)

def FIRST_DAY(s):
    return IS_DAY1(s) or IS_NIGHT1(s)

def FOUND_ALL_FROGS(s):
    return s.weekeventreg('WEEKEVENTREG_33_01') and s.weekeventreg('WEEKEVENTREG_32_40') and s.weekeventreg('WEEKEVENTREG_32_80') and s.weekeventreg('WEEKEVENTREG_33_02')

def GBT_CAN_REVERSE_WATER_FLOW(s):
    return s.event('RE_GREAT_BAY_RED_SWITCH_1') and s.event('RE_GREAT_BAY_RED_SWITCH_2') and s.has_item('ITEM_HOOKSHOT')

def GBT_GREEN_SWITCH_FLOW(s):
    return s.event('RE_GREAT_BAY_GREEN_SWITCH_1') and s.event('RE_GREAT_BAY_GREEN_SWITCH_2') and s.event('RE_GREAT_BAY_GREEN_SWITCH_3')

def IS_DAY(s):
    return IS_DAY1(s) or IS_DAY2(s) or IS_DAY3(s)

def IS_DAY1(s):
    return s.raw_before(TIME_NIGHT1_PM_06_00) and CLOCK_DAY1(s)

def IS_DAY2(s):
    return s.raw_between(TIME_DAY2_AM_06_00, TIME_NIGHT2_PM_06_00) and CLOCK_DAY2(s)

def IS_DAY3(s):
    return s.raw_between(TIME_DAY3_AM_06_00, TIME_NIGHT3_PM_06_00) and CLOCK_DAY3(s)

def IS_NIGHT(s):
    return IS_NIGHT1(s) or IS_NIGHT2(s) or IS_NIGHT3(s)

def IS_NIGHT1(s):
    return s.raw_between(TIME_NIGHT1_PM_06_00, TIME_DAY2_AM_06_00) and CLOCK_NIGHT1(s)

def IS_NIGHT2(s):
    return s.raw_between(TIME_NIGHT2_PM_06_00, TIME_DAY3_AM_06_00) and CLOCK_NIGHT2(s)

def IS_NIGHT3(s):
    return s.raw_after(TIME_NIGHT3_PM_06_00) and CLOCK_NIGHT3(s)

def MIDNIGHT(s):
    return s.time_between(TIME_NIGHT1_AM_12_00, TIME_DAY2_AM_06_00) or s.time_between(TIME_NIGHT2_AM_12_00, TIME_DAY3_AM_06_00) or s.time_after(TIME_NIGHT3_AM_12_00)

def MeetsMoonRequirements(s):
    return (s.remains_count() >= s.opt('RO_ACCESS_MOON_REMAINS_COUNT')) and (s.moon_mask_count() >= s.opt('RO_ACCESS_MOON_MASKS_COUNT'))

def SECOND_DAY(s):
    return IS_DAY2(s) or IS_NIGHT2(s)

def SettingClocks(s):
    return s.opt('RO_CLOCK_SHUFFLE') != 0

