def CanKillEnemy(s, actor):
    if s.opt('RO_SHUFFLE_ENEMY_SOULS') and not s.have_enemy_soul(actor):
        return False
    fn = CAN_KILL_ENEMY.get(actor)
    if fn is None:
        raise KeyError(f'CanKillEnemy: no logic for {actor}')
    return fn(s)

